 const[month,setMonth]=useState(initialMonth),[days,setDays]=useState([]),[calendarBusy,setCalendarBusy]=useState(true),[calendarVersion,setCalendarVersion]=useState(0),[start,setStart]=useState(''),[end,setEnd]=useState(''),[quantity,setQuantity]=useState(1),[priceUnit,setPriceUnit]=useState(item?.dailyPrice!=null?'DAILY':'MONTHLY'),[discount,setDiscount]=useState(''),[message,setMessage]=useState(''),[negotiationMessage,setNegotiationMessage]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState('');
 const[idempotencyKey,setIdempotencyKey]=useState(''),[keyVersion,setKeyVersion]=useState(0),[keyBusy,setKeyBusy]=useState(false);
 useEffect(()=>{let active=true;if(!user){setIdempotencyKey('');setKeyBusy(false);return()=>{active=false}}setIdempotencyKey('');setKeyBusy(true);api('/booking-key',{method:'POST'}).then(data=>{if(active&&typeof data.idempotencyKey==='string')setIdempotencyKey(data.idempotencyKey);else if(active)setError('Could not prepare a secure booking request. Refresh and try again.')}).catch(e=>{if(active)setError(e.message||'Could not prepare a secure booking request.')}).finally(()=>{if(active)setKeyBusy(false)});return()=>{active=false}},[user?.id,keyVersion]);
 const monthFirst=dateKeyFromUTC(month),today=dateKeyFromUTC(new Date()),calendarWeekday=new Date(`${monthFirst}T00:00:00Z`).getUTCDay(),calendarStart=shiftDateKey(monthFirst,-calendarWeekday),calendarEnd=shiftDateKey(calendarStart,42);
 useEffect(()=>{let active=true;if(!item?.id){setDays([]);setCalendarBusy(false);setError('Listing data is incomplete. Reload the page and try again.');return()=>{active=false}}setCalendarBusy(true);api(`/listings/${item.id}/availability?from=${calendarStart}&to=${calendarEnd}`).then(data=>{if(active){if(Array.isArray(data.days)&&data.days.every(day=>day&&typeof day.date==='string'&&Number.isFinite(day.remaining))){setDays(data.days);setError('')}else{setDays([]);setError('Availability data could not be read. Reload the page and try again.')}}}).catch(e=>{if(active)setError(e.message)}).finally(()=>{if(active)setCalendarBusy(false)});return()=>{active=false}},[item?.id,calendarStart,calendarEnd,calendarVersion]);
