 const clickDate=key=>{setError('');if(key<today)return;const availability=dayMap.get(key);if(!start||end||key<=start){if(!availability||availability.remaining<quantity){setError('That start date does not have enough available units.');return}setStart(key);setEnd('');return}const interval=days.filter(day=>day.date>=start&&day.date<key);if(interval.length!==dayCountForRange(start,key)||interval.some(day=>day.remaining<quantity)){setError('That range includes dates without enough available units.');return}setEnd(key)};
